<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {useRouter} from 'vue-router'
import {session,logout,clearSession,ApiError} from '../auth'
const router=useRouter(),menuOpen=ref(false),orders=ref<any[]>([]),nextCursor=ref<string|null>(null),loaded=ref(false),message=ref(''),pendingCancel=ref<string|null>(null),recoveryId=ref<string|null>(null),candidates=ref<any[]>([]),fillOrder=ref<string|null>(null),fills=ref<any[]>([]),fillsTruncated=ref(false),attachId=ref(''),ack=ref(false)
async function api(path:string,options:RequestInit={}){const r=await fetch('/api/v1'+path,{credentials:'same-origin',cache:'no-store',...options});const b=await r.json();if(!r.ok)throw new Error(b?.error?.message||'请求失败');return b.data}
async function load(append=false){try{const q=new URLSearchParams({limit:'20'});if(append && nextCursor.value)q.set('cursor',nextCursor.value);const data=await api('/trade-intents?'+q);orders.value=append?[...orders.value,...data.items]:data.items;nextCursor.value=data.next_cursor;loaded.value=true}catch{message.value='订单状态加载失败。'}}
const stateName=(s:string)=>({submitting:'提交中',pending:'已接受，待核对',partially_filled:'部分成交',filled:'全部成交',rejected:'已拒绝',cancelled:'已撤单',unknown:'结果未知'} as Record<string,string>)[s]||'未知'
const cancelName=(s:string)=>({submitting:'撤单中',unknown:'撤单结果未知',confirmed:'已确认撤单',rejected:'撤单被拒绝'} as Record<string,string>)[s]||'未知'
async function action(id:string,kind:'cancel'|'reconcile'){try{await api(kind==='cancel'?'/single-orders/'+id+'/cancel':'/trade-intents/'+id+'/reconcile',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:'{}'});pendingCancel.value=null;message.value=kind==='cancel'?'撤单请求已处理，请查看状态。':'已安排只读对账。';await load()}catch{message.value='请求结果未确认，请刷新或安排只读对账。'}}
async function loadFills(id:string){try{const data=await api('/trade-intents/'+id+'/fills');fillOrder.value=id;fills.value=data.items;fillsTruncated.value=data.truncated;message.value='已查询交易所成交记录。'}catch(e){message.value=e instanceof Error?e.message:'成交记录查询失败。'}}
async function findCandidates(id:string){recoveryId.value=id;candidates.value=[];attachId.value='';ack.value=false;try{const data=await api('/trade-intents/'+id+'/reconcile-candidates');candidates.value=data.items;message.value=data.truncated?'候选可能不完整，请到 Polymarket 独立核查。':'候选仅包括未完成订单；请独立核实。'}catch{message.value='候选订单查询失败，请稍后重试。'}}
async function attach(){if(!recoveryId.value||!ack.value)return;try{await api('/trade-intents/'+recoveryId.value+'/attach-order',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':session.csrf},body:JSON.stringify({order_id:attachId.value,acknowledge_uncertainty:true})});message.value='订单编号已关联，状态仍需只读对账。';recoveryId.value=null;await load()}catch(e){message.value=e instanceof Error?e.message:'订单编号关联失败。'}}
async function signOut(){try{await logout();await router.replace('/login')}catch(e){if(e instanceof ApiError&&e.status===401){clearSession();await router.replace('/login')}else message.value='退出请求未确认，请重试。'}}
onMounted(()=>load())
</script>
<template><div class="app-layout"><header class="mobile-header"><div class="brand"><span class="brand-mark">P</span> PolySports</div><button class="menu-button" :aria-expanded="menuOpen" aria-controls="primary-nav" @click="menuOpen=!menuOpen">菜单</button></header><aside id="primary-nav" class="sidebar" :class="{open:menuOpen}"><div class="brand sidebar-brand"><span class="brand-mark">P</span> PolySports</div><p class="nav-label">工作台</p><nav aria-label="主导航"><RouterLink to="/">总览</RouterLink><RouterLink to="/sports/football">足球赛事</RouterLink><RouterLink to="/sports/nba">NBA 赛事</RouterLink><span aria-disabled="true">组合交易 <small>即将开放</small></span><RouterLink to="/orders">交易记录</RouterLink><RouterLink to="/wallets">钱包状态</RouterLink><RouterLink to="/system">系统管理</RouterLink></nav></aside><main class="workspace"><div class="workspace-top"><span class="breadcrumb">工作台 / 交易记录</span><div class="account"><span>{{session.username}}</span><button class="text-button" @click="signOut">退出</button></div></div><div class="page-heading"><div><p class="eyebrow">ORDER STATUS</p><h1>单场订单</h1><p class="muted">已接受不等于已成交；未知状态须对账，不能重复提交。</p></div></div><p role="status" class="form-message">{{message}}</p><button class="text-button" @click="load()">刷新订单</button><section class="welcome-card"><p v-if="loaded && !orders.length">暂无已记录订单。</p><article v-for="order in orders" :key="order.id" class="market-card"><h2>{{order.side==='BUY'?'买入':'卖出'}} · {{stateName(order.state)}}</h2><p>{{order.home}} 对 {{order.away}} · {{order.market_question}} · {{order.outcome_label}}</p><p>限价 {{order.limit_price}} · 份额 {{order.size}} · 已成交 {{order.matched_size ?? '未知'}}</p><p class="id-text">交易所订单 ID：{{order.external_order_id || '未知'}}</p><p v-if="order.error_code">状态说明：{{order.error_code}}<span v-if="order.retry_after_seconds!==null"> · 建议等待 {{order.retry_after_seconds}} 秒</span></p><p v-if="order.cancel_state">撤单状态：{{cancelName(order.cancel_state)}}</p><button v-if="order.external_order_id" class="text-button" @click="loadFills(order.id)">查询成交记录</button><div v-if="fillOrder===order.id"><p>成交状态由交易所提供，未确认状态不等于结算完成。</p><p v-if="!fills.length">当前查询未返回成交记录。</p><p v-if="fillsTruncated">结果可能不完整，请到交易所核查。</p><p v-for="fill in fills" :key="fill.trade_id" class="id-text">{{fill.trade_id}} · {{fill.size}} 份 · 价格 {{fill.price}} · {{fill.status}}</p></div><button class="text-button" @click="action(order.id,'reconcile')">安排只读对账</button><button v-if="order.state==='unknown' && !order.external_order_id" class="text-button" @click="findCandidates(order.id)">查找相似未完成订单</button><div v-if="recoveryId===order.id" class="mapping-confirm"><p>候选仅按参数筛选，不证明属于本次提交。请到 Polymarket 独立核对订单编号；未出现不代表订单不存在。</p><p v-for="candidate in candidates" :key="candidate.order_id" class="id-text">{{candidate.order_id}} · {{candidate.created_at}} · {{candidate.status}}</p><label :for="'attach-'+order.id">经独立核实的交易所订单 ID</label><input :id="'attach-'+order.id" v-model="attachId" placeholder="0x…" maxlength="66"><label><input v-model="ack" type="checkbox">我已独立核实该编号属于本次订单</label><button class="text-button" :disabled="!ack || !attachId" @click="attach">关联并继续只读对账</button></div><button v-if="order.external_order_id && ['pending','partially_filled','unknown'].includes(order.state) && (!order.cancel_state || order.cancel_state==='rejected')" class="text-button" @click="pendingCancel=order.id">撤单</button><div v-if="pendingCancel===order.id"><p>确认向交易所撤销此订单？</p><button class="text-button" @click="pendingCancel=null">返回</button><button class="text-button" @click="action(order.id,'cancel')">确认撤单</button></div></article><button v-if="nextCursor" class="text-button" @click="load(true)">加载更多</button></section></main></div></template>
